1	//! Static lowering/bundle skew guard: every `(module, function, arity)` the
2	//! MIR lowering may mint (`RuntimeFn::import_surface`) must be exported by a
3	//! module shipped in the embedded SDK closure.
4	//!
5	//! This is the guard the `map_settled` incident demanded: the lowering grew a
6	//! `RuntimeFn` row (`aion@workflow:map_settled/2`) while the committed
7	//! closure predated the SDK function, so tolerant single-activity distribute
8	//! archives crashed a running VM with `undef` — a skew no compile step could
9	//! see. With this test, a runtime row the closure does not export fails CI
10	//! the moment it is introduced.
11	
12	use std::collections::{BTreeMap, BTreeSet};
13	
14	use aion_awl::mir::RuntimeFn;
15	use aion_awl_package::sdk_closure_modules;
16	use beamr::atom::AtomTable;
17	use beamr::loader::load_beam_chunks;
18	
19	type TestResult = Result<(), Box<dyn std::error::Error>>;
20	
21	/// Modules the Erlang runtime itself provides. `RuntimeFn::IntAdd` is the one
22	/// BIF-position row (`erlang:'+'/2`); beamr resolves it natively, so no
23	/// bundle module can or should export it.
24	const VM_PROVIDED_MODULES: &[&str] = &["erlang"];
25	
26	/// Module name → exported `(function, arity)` set.
27	type ExportMap = BTreeMap<String, BTreeSet<(String, u32)>>;
28	
29	/// The export map of the embedded closure, read through the same beamr
30	/// chunk loader the engine uses.
31	fn closure_exports() -> Result<ExportMap, Box<dyn std::error::Error>> {
32	    let atoms = AtomTable::with_common_atoms();
33	    let mut exports = BTreeMap::new();
34	    for (name, bytes) in sdk_closure_modules() {
35	        let parsed = load_beam_chunks(bytes, &atoms)?;
36	        let mut set = BTreeSet::new();
37	        for export in &parsed.exports {
38	            let Some(function) = atoms.resolve(export.function) else {
39	                return Err(format!(
40	                    "module `{name}` has an unresolvable export atom: {:?}",
41	                    export.function
42	                )
43	                .into());
44	            };
45	            set.insert((function.to_owned(), u32::from(export.arity)));
46	        }
47	        exports.insert(name.to_owned(), set);
48	    }
49	    Ok(exports)
50	}
51	
52	/// Every runtime signature the lowering may mint is exported by a shipped
53	/// closure module (VM-provided modules excepted).
54	#[test]
55	fn every_runtime_fn_signature_is_exported_by_the_closure() -> TestResult {
56	    let exports = closure_exports()?;
57	    let surface = RuntimeFn::import_surface();
58	    // Vacuous-pass guards: the surface and the closure must both be
59	    // non-trivial, and the incident row itself must be present.
60	    assert!(surface.len() > 50, "runtime surface shrank suspiciously");
61	    assert!(!exports.is_empty(), "closure export map is empty");
62	    assert!(
63	        surface.iter().any(|(module, function, arity)| {
64	            *module == "aion@workflow" && function == "map_settled" && *arity == 2
65	        }),
66	        "the surface no longer carries aion@workflow:map_settled/2 — update this guard's anchors"
67	    );
68	
69	    let mut missing = Vec::new();
70	    for (module, function, arity) in surface {
71	        if VM_PROVIDED_MODULES.contains(&module) {
72	            continue;
73	        }
74	        let exported = exports
75	            .get(module)
76	            .is_some_and(|set| set.contains(&(function.clone(), arity)));
77	        if !exported {
78	            missing.push(format!("{module}:{function}/{arity}"));
79	        }
80	    }
81	    assert!(
82	        missing.is_empty(),
83	        "runtime rows the embedded SDK closure does not export (each would be an `undef` crash \
84	         in a deployed direct archive): {missing:?}"
85	    );
86	    Ok(())
87	}

